nextflow_process {

    name "Test Process TELOMEREHUNTER2"
    script "../main.nf"
    process "TELOMEREHUNTER2"

    tag "modules"
    tag "modules_nfcore"
    tag "telomerehunter2"

    test("sarscov2 - bam") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true),
                    [],
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert path(process.out.summary[0][1]).exists() },
                { assert path(process.out.summary[0][1]).text.contains("tel_content") },
                { assert path(process.out.file_index[0][1]).exists() },
                { assert path(process.out.outdir[0][1]).exists() }
            )
        }

    }

    test("sarscov2 - bam - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true),
                    [],
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert process.out.summary },
                { assert process.out.file_index },
                { assert process.out.outdir },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

